"""Draft skeleton of the methodology memo docs/methodology/counting-a-participant.md.

Every section heading, every counting rule C1-C15 and every number are in place, pulled from the marts. Every prose paragraph
is marked `<!-- DRAFT: Anna to rewrite -->`: the final prose is Anna's. Numbers sit in tables marked
`<!-- numbers: ... -->`.

  uv run python -m scripts.build_methodology_memo           writes the draft only if the memo does not exist
  uv run python -m scripts.build_methodology_memo --force   overwrites (it would destroy rewritten prose; refuses otherwise)
"""
from __future__ import annotations

import sys

import duckdb
from scripts.common import DB, ROOT

OUT = ROOT / "docs" / "methodology" / "counting-a-participant.md"
DRAFT = "<!-- DRAFT: Anna to rewrite -->"
NUM = "<!-- numbers: generated by scripts/build_methodology_memo.py from the marts -->"

RULES = [  # id, plain-language rule
    ("C1", "A participant is a resolved person with at least one valid registration in the year. We count people, not registrations."),
    ("C2", "A registration is valid unless it is an exact duplicate (a double submit or a repeated page) or falls outside the reporting period. A registration with an impossible date of birth still counts: the person is real, only the date is wrong."),
    ("C3", "The global reporting period is the calendar year. US spring and fall roll up into one year, so US numbers are comparable with Canadian and international annual seasons."),
    ("C4", "For the US only there is a separate spring and fall view. It is never blended with the annual sources."),
    ("C5", "A person registered in two leagues in one year is counted once globally and once in each organization's own count."),
    ("C6", "A person registered in two countries in one year is counted once globally. In the additive country view they belong to the country of their most recent registration that year; in the presence view they are counted in each country they played in."),
    ("C7", "Age is age on December 31 of the year (for Canadian records that give only a birth year: year minus birth year)."),
    ("C8", "A person in two divisions in one year has a primary division (the one with the most registrations, ties to the most recent); all of their divisions are kept."),
    ("C9", "Sex is the registration-reported sex. Unknown stays unknown and is reported as its own group; it is never guessed."),
    ("C10", "Youth means 17 or under on December 31."),
    ("C11", "A new participant is in their first valid year. The first year of data is left out of new and returning counts, because everyone would look new."),
    ("C12", "A returning participant has a valid registration this year and last year."),
    ("C13", "A reactivated participant has a valid registration this year, none last year, and at least one earlier."),
    ("C14", "Records in clusters with an open identity issue are counted, and the number of such participants is reported alongside."),
    ("C15", "A count is registered participants in onboarded sources. It is not total flag football participation: informal play, non-partner leagues and attendance are out of scope."),
]


def md_table(header: list[str], rows: list[list]) -> str:
    fmt = lambda v: "" if v is None else (f"{v:,.0f}" if isinstance(v, (int, float)) and not isinstance(v, bool) and float(v).is_integer() else str(v))  # noqa: E731
    year_col = header[0] == "Year"      # a year is a label, not a quantity: no thousands separator
    cell = lambda i, c: str(c) if (year_col and i == 0) else fmt(c)  # noqa: E731
    return "\n".join(["| " + " | ".join(header) + " |", "|" + "---|" * len(header)]
                     + ["| " + " | ".join(cell(i, c) for i, c in enumerate(r)) + " |" for r in rows])


def render(con: duckdb.DuckDBPyConnection) -> str:
    q = lambda sql, *a: con.execute(sql, list(a)).fetchall()  # noqa: E731
    year = q("select max(participation_year) from measurement.mart_participation_global")[0][0]
    version = q("select max(methodology_version) from measurement.mart_participation_global")[0][0]
    version_num = int(version.split(".")[0]) * 1000 + int(version.split(".")[1])
    g = q("select participation_year, unique_participants, registrations, new_participants, returning_participants, "
          "reactivated_participants, censored_participants, retention_rate, multi_org_participants, multi_country_participants "
          "from measurement.mart_participation_global order by 1")
    cur = {r[0]: r for r in g}[year]
    raw_regs = q("select count(*) from marts.bridge_registration_participant")[0][0]
    survivors = q("select count(*) from identity.idr_input_records")[0][0]
    participants_all = q("select count(*) from marts.dim_participant")[0][0]
    invalid = q("select count(*) from facts.fct_registration where not is_valid_registration")[0][0]
    impossible_valid = q("select count(*) from facts.fct_registration f join intermediate.int_registrations_unioned r using (registration_key) "
                         "where f.is_valid_registration and r.is_impossible_dob")[0][0]
    open_issue = q("select count(*) from facts.fct_participant_year where participation_year = ? and has_open_integrity_issue", year)[0][0]
    unknown_sex = q("select count(*) from facts.fct_participant_year where participation_year = ? and sex = 'U'", year)[0][0]
    attributed = q("select sum(participants_attributed), sum(participants_present), count(*) from measurement.mart_participation_by_country where participation_year = ?", year)[0]
    country_rows = q("select country_code, participants_attributed, participants_present from measurement.mart_participation_by_country where participation_year = ? order by 1", year)
    bounds = q("select participation_year, participants_low, participants_point, participants_high, round(range_pct * 100, 2), participants_touched_by_review, open_review_items "
               "from measurement.mart_identity_uncertainty where grain = 'GLOBAL' order by 1")
    truth = q("select participation_year, true_participants, participants_low, participants_point, participants_high, truth_within_range, point_error "
              "from evaluation.eval_participation_accuracy where grain = 'GLOBAL' order by 1")
    country_truth = q("select count(*) filter (where truth_within_range), count(*) from evaluation.eval_participation_accuracy where grain = 'COUNTRY'")[0]
    sex = q("select participation_year, sex, participants, suppressed from share_exec.share_exec__participation_by_sex where participation_year in "
            "(select participation_year from share_exec.share_exec__participation_by_sex where suppressed <> 'NONE') order by 1, sex nulls first")
    marketing = q("select count(*), count(*) filter (where contact_role = 'GUARDIAN_OF_MINOR') from share_marketing.share_marketing__contact_list")[0]
    emails = q("select count(distinct contact_email) from marts.dim_participant where contact_email is not null")[0][0]
    media = q("select count(*), count(distinct first_name || '|' || last_name) from share_media.share_media__roster")[0]
    photo = q("select consent_photo, count(*) from marts.dim_participant group by 1")
    kmin = q("select value from reference.privacy_params where param = 'k_min'")[0][0]
    sources = q("select count(*) filter (where onboarding_status in ('Modelled', 'Production')), count(*) from reference.source_registry")[0]
    status_rows = [[y, u, n, r, rea, c] for y, u, _, n, r, rea, c, *_ in g]

    def p(text: str) -> str:
        return f"{DRAFT}\n{text}\n"

    parts = [f"""# Counting a participant

> **Synthetic data.** Every number in this memo describes a generated population, not a real program. **DRAFT SKELETON:** every
> heading, rule and number is in place; each prose paragraph is marked `<!-- DRAFT: Anna to rewrite -->` and is for Anna to write.
> Audience: a program executive and a privacy lead. Methodology version **{version}**.
"""]
    parts += ["## 1. What we count, and what we don't\n",
              p(f"We count **registered participants in the sources we have onboarded**: {sources[0]} of the {sources[1]} sources we know about (the other "
                "two are planned for a later phase). In {0} that is **{1:,} unique participants**, from {2:,} valid registrations. This is not total flag football "
                "participation: informal play, leagues outside our partners and attendance are not in the data.".format(year, cur[1], cur[2])),
              p("**A registration is not proof of play.** We have no attendance data, so a registered participant may never have played a game. "
                "Read every number in this memo as 'signed up', not 'showed up'."),
              NUM, md_table(["Year", "Unique participants", "Valid registrations"], [[y, u, r] for y, u, r, *_ in g]), ""]
    parts += ["## 2. Who counts as one person\n",
              p(f"The same child appears under different spellings, in different leagues, clubs and countries, and sometimes with a mistyped birthday. We decide "
                f"which registrations belong to one person with a transparent, rule-and-evidence matcher built in SQL: it links records that a source itself "
                f"says are the same person, compares names, dates of birth, contact details and context for plausible pairs, and sends uncertain pairs to a person "
                f"to decide. {raw_regs:,} registrations resolve to {participants_all:,} participants. See [how identity resolution works](../identity_resolution.md)."),
              p("We are deliberately careful: we would rather leave two records of one child apart than merge two children into one. A wrong merge undercounts "
                "participation and can apply one child's consent to a sibling. The matcher's measured accuracy is in [Phase 2 results](../phase2_results.md)."),
              ""]
    parts += ["## 3. The counting rules\n",
              p("These fifteen rules are the methodology. They are implemented once, in the counting tables, and every report reads from them."),
              "| # | Rule |\n|---|---|\n" + "\n".join(f"| {i} | {t} |" for i, t in RULES), "",
              NUM,
              md_table(["Rule", f"What it looks like in {year}", "Number"],
                       [["C2", "registrations that are not valid (exact duplicates)", invalid],
                        ["C2", "valid registrations with an impossible date of birth (counted)", impossible_valid],
                        ["C5", "participants registered in two or more organizations", cur[8]],
                        ["C6", "participants who played in two countries in the year", cur[9]],
                        ["C9", "participants whose sex is unknown (own group, never imputed)", unknown_sex],
                        ["C14", "participants in clusters with an open identity issue (counted, reported here)", open_issue]]),
              "", "**Growth status by year** (C11 to C13):", "", NUM,
              md_table(["Year", "Unique participants", "New", "Returning", "Reactivated", "First data year (censored)"], status_rows), "",
              p("**Worked example (a made-up girl).** In year one she plays spring in one Texas league and fall in another, then moves to Ontario and plays there in year two. "
                "She is **one participant in each year** (C1). In year one she has **two registrations** and is a **multi-organization** participant (C5); in year two she has one. "
                "Her year-one status is new (or first-data-year if year one is the first year of data) and in year two **returning** (C12), so she adds to the retention numerator. "
                "In the US seasonal view she appears in the spring and the fall of year one, as new in each (C4). By country she is a **US participant in year one and a Canadian one in year two** "
                "in the additive view. If she had moved mid-year and played in both countries in the same year, she would still be **one** global participant, attributed to Canada "
                "(her most recent registration, C6), and would appear in both countries only in the presence view."),
              ""]
    parts += ["## 4. Global versus country numbers\n",
              p("Country totals in the presence view add up to **more** than the global number whenever someone plays in two countries. We publish both views and label them: use "
                "**attributed** for any total, and **present** for the question 'who played here'. The two differ by exactly the number of extra countries people played in."),
              NUM,
              md_table(["Country", "Participants (attributed, adds up)", "Participants (present, overlaps)"], [[c, a, pr] for c, a, pr in country_rows]),
              f"\nAttributed sums to {attributed[0]:,}, equal to the global figure; present sums to {attributed[1]:,}, {attributed[1] - attributed[0]:,} more (people counted in two countries).\n"]
    parts += ["## 5. How sure are we?\n",
              p("We give every headline number a range for the part we can measure: what identity resolution alone could change. The **low** bound assumes every uncertain pair is really one "
                "person; the **high** bound assumes every cluster flagged as suspicious is really several people. It uses no answer key, so it works on real data too."),
              NUM,
              md_table(["Year", "Low", "Reported (point)", "High", "Range % of point", "Participants touched by open review items", "Open review items"], [list(r) for r in bounds]),
              p("**The range covers identity only.** It does not cover sources we do not have, data-entry errors inside a source, or an error the pipeline cannot see. "
                "It is therefore a floor on our uncertainty, not a confidence interval for 'how many people play flag football'."),
              "**Compared with the synthetic truth (available only because this data is generated):**", "", NUM,
              md_table(["Year", "True participants", "Low", "Reported", "High", "Truth inside range?", "Reported minus true"], [list(r) for r in truth]),
              p(f"In every year the truth falls inside the range, and by country in {country_truth[0]} of {country_truth[1]} cells. Do not read that as proof the range is conservative: the matcher is "
                "very accurate on this clean synthetic data, and the two country cells it misses show the range cannot see an error the pipeline does not flag."),
              ""]
    sex_rows = [[y, s if s else "all", pc if pc is not None else "suppressed", sup] for y, s, pc, sup in sex]
    parts += ["## 6. Privacy by design\n",
              p("Each audience sees only what it needs: **executives** see aggregates, with small numbers suppressed; **analysts** see pseudonymous participant-year rows (birth year, not birth "
                "date; a postal prefix, not a postal code; no names or contact details); **operations** see full identifiers because they run the leagues; **marketing** gets only contact addresses "
                "with consent; **media** gets only people cleared for photos. These are project policies informed by rules such as COPPA, CASL and GDPR, not legal interpretations."),
              p(f"**Small numbers are suppressed.** Any count from 1 to {int(kmin) - 1} is hidden. If hiding it would let a reader work it out from a published total, a second cell is hidden too. "
                "Example from the executive share:"),
              NUM, md_table(["Year", "Sex", "Participants", "Suppression"], sex_rows), "",
              p(f"**Consent that was not captured is not consent.** Of {emails:,} contact addresses, {marketing[0]:,} are on the marketing list ({marketing[1]:,} are guardians of minors): an address is "
                "included only if **everyone** who shares it has said yes, so a guardian's yes for one child is never assumed for a sibling. No minor's own details are ever on the list. The photo "
                f"roster has {media[0]:,} participant-organization-season rows for {media[1]:,} people; anyone with a refusal **or** no recorded answer is simply absent, meaning not cleared."),
              p("**Pseudonymous is not anonymous.** The analyst share is hard to link back without the key, but combining birth year, postal prefix, sex and country singles out many people. "
                "That is why analyst access needs a stated purpose (ADR-006 gives the measured risk)."),
              ""]
    parts += ["## 7. When numbers change\n",
              p("Published numbers are versioned. Each year's scorecard is saved as an immutable snapshot, and a log compares today's numbers with what was published and names a likely cause: "
                "new source data, a change in who is linked to whom, or a change in the counting rules. A headline number is reissued only if it moves by more than 1% (a percentage point for "
                "rates) or the methodology changes, and a person must approve it and record it in the changelog. A recorded demonstration is in "
                "[restatement_demo.md](../reports/restatement_demo.md): one steward decision moved a 2025 headline number by one person and was logged, with no reissue required."),
              ""]
    reach = q("select participation_year, reported_headcount, voluntary_headcount, combined_reach_low, combined_reach_high "
              "from measurement.mart_reported_headcount where country_code = 'ALL' order by 1") if version_num >= 1001 else []
    if reach:
        aggregate = ("**Aggregate-only sources.** School and recreation program headcounts (Source E) are reported as a separate line, 'reported headcount', and are never added to unique "
                     "participants: a count of children in a program cannot be matched to people, so some of those children are also registered participants and some are counted in more than one "
                     "program. We therefore publish a **combined reach range** (low end: as much overlap as is possible; high end: none), not a single number. Physical education units are exposure "
                     "during class, not participation, so the voluntary headcount (intramural and after-school) is shown separately. Programs with fewer than 10 reporting in a country-year are suppressed.")
    else:
        aggregate = ("**Aggregate-only sources** (school counts, coming in a later phase) will be reported as a separate, non-deduplicated 'reported headcount' line and never mixed into "
                     "resolved participants.")
    parts += ["## 8. Known limitations and next steps\n",
              p(f"**Coverage.** {sources[0]} sources are onboarded; counts are only as complete as our partners' registration data. {aggregate} **Attendance** is not measured. **Real-world validation** has not "
                "happened: this memo describes a synthetic population in which phone numbers never change and one nickname list covers every case, so real data would score lower."),
              ""]
    if reach:
        parts += [NUM, md_table(["Year", "Reported headcount", "Of which voluntary", "Combined reach, low", "Combined reach, high"], reach), ""]
    parts += ["## 9. Version and change control\n",
              p(f"This is methodology **version {version}**. Every scorecard row and every published snapshot carries the version. Changes to a rule bump the version and are recorded in the "
                "[CHANGELOG](CHANGELOG.md); see [ADR-005](../decisions/ADR-005-counting-rules.md), [ADR-006](../decisions/ADR-006-privacy-controls.md) and "
                "[ADR-007](../decisions/ADR-007-publish-and-restatement.md) for the decisions behind it."
                + (" Version 1.1 added the reported-headcount and combined-reach KPIs (new, so nothing published was restated). The data window now runs "
                   f"{q('select first_observed_year from reference.observation_window')[0][0]} to {year}, and {q('select first_observed_year from reference.observation_window')[0][0]} is the "
                   "first data year, so new, returning and retention figures are not defined for it." if version_num >= 1001 else "")),
              ""]
    return "\n".join(parts)


def main(argv: list[str]) -> int:
    if OUT.exists() and "--force" not in argv:
        print(f"{OUT} already exists: refusing to overwrite rewritten prose (use --force to replace it)", file=sys.stderr)
        return 1
    con = duckdb.connect(str(DB), read_only=True)
    try:
        text = render(con)
    finally:
        con.close()
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(text, encoding="utf-8")
    print(f"wrote {OUT.relative_to(ROOT)} ({text.count(DRAFT)} draft paragraphs for Anna to rewrite)")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
